mapper.select:
SELECT hs.account_id, hs.security_id, hs.snapshot_date, hs.quantity, hs.average_cost, hs.market_value, hs.unrealized_pnl FROM holding_snapshots hs INNER JOIN ( SELECT account_id, security_id, MAX(snapshot_date) AS snapshot_date FROM holding_snapshots WHERE account_id IN
#{accountId}
GROUP BY account_id, security_id ) latest ON latest.account_id = hs.account_id AND latest.security_id = hs.security_id AND latest.snapshot_date = hs.snapshot_date WHERE hs.account_id IN
#{accountId}
AND hs.security_id = #{securityId}
